create function pg_temp.appliquer_a0() returns void language plpgsql as $test_a0$ begin execute $sql_a0$do $a0$
declare
  manifeste constant jsonb := '{"associations":[{"event_id":"EVT-0008","pack_id":"COL-0112","reason":"Premier scrutin national des Françaises ; distinct des municipales, déjà présentes.","snapshot":{"id":"EVT-0008","packs":["COL-0061","COL-0062","COL-0073","COL-0082"],"title":"Premier vote des Françaises à un scrutin national","niveau":1,"topics":["Construction de l’État","Démocratie","Droits et libertés","Femmes et genre","Histoire sociale","Politique"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":21,"start_year":1945,"date_status":"EXACT","description":"Les Françaises participent pour la première fois à un vote national. Elles choisissent des députés et répondent à un référendum sur l''organisation du pays.","start_month":10,"playable_mode":"DAY","titre_question":null},"verified_sources":[{"url":"https://www.assemblee-nationale.fr/dyn/histoire-et-patrimoine/seconde-guerre-mondiale/des-deputees-a-l-assemblee-nationale","evidence":"Premier scrutin national du 21 octobre 1945 confirmé par l’Assemblée.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0414","pack_id":"COL-0112","reason":"Jalon majeur de l’imprimerie ; conserver le statut et la précision du canon, sans créer une seconde Bible de Gutenberg.","snapshot":{"id":"EVT-0414","packs":["COL-0060","COL-0062","COL-0072","COL-0079"],"title":"Impression de la Bible de Gutenberg","niveau":1,"topics":["Arts et culture","Explorations","Religions"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"YEAR","start_day":null,"start_year":1455,"date_status":"APPROXIMATE","description":"Impression de la Bible de Gutenberg — repère complémentaire du chapitre « Événements complémentaires directement utiles au thème 3 », daté vers 1455.","start_month":null,"playable_mode":"YEAR","titre_question":null},"verified_sources":[{"url":"https://loc.gov/exhibits/bibles/the-gutenberg-bible.html","evidence":"Impression probablement achevée fin 1455 ; statut APPROXIMATE et année seule conservés. Ne pas présenter comme première impression mondiale : la typographie asiatique est antérieure.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0713","pack_id":"COL-0112","reason":"Jalon du brevet de Bell, sans lui attribuer toute l’invention du téléphone.","snapshot":{"id":"EVT-0713","packs":["COL-0060","COL-0081","COL-0113"],"title":"Brevet du téléphone accordé à Alexander Graham Bell","niveau":1,"topics":["Médias et information","Techniques et technologies"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":7,"start_year":1876,"date_status":"EXACT","description":"Brevet du téléphone accordé à Alexander Graham Bell. Repère daté de 7 mars 1876, lié à Médias et information et Techniques et technologies, avec un ancrage principal en Amérique du Nord et États-Unis.","start_month":3,"playable_mode":"DAY","titre_question":null},"verified_sources":[{"url":"https://www.si.edu/collections/snapshot/alexander-graham-bells-large-box-telephone","evidence":"Brevet accordé à Bell le 7 mars 1876 confirmé par Smithsonian ; distinction invention/brevet conservée.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0286","pack_id":"COL-0112","reason":"Premier satellite artificiel ; compléter le premier vol humain déjà présent.","snapshot":{"id":"EVT-0286","packs":["COL-0060","COL-0062","COL-0065","COL-0070","COL-0082"],"title":"Lancement de Spoutnik 1","niveau":1,"topics":["Espace","Frontières et territoires","Géopolitique","Techniques et technologies"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":4,"start_year":1957,"date_status":"EXACT","description":"L''Union soviétique place Spoutnik en orbite, premier satellite artificiel de la Terre. Le succès ouvre l''ère spatiale et transforme la rivalité scientifique et stratégique entre les puissances.","start_month":10,"playable_mode":"DAY","titre_question":"Lancement de Spoutnik 1, premier satellite artificiel"},"verified_sources":[{"url":"https://www.nasa.gov/history/story-of-explorer-1/","evidence":"NASA : premier satellite artificiel lancé le 4 octobre 1957.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0289","pack_id":"COL-0112","reason":"Premier alunissage habité ; ne pas confondre avec le premier pas en UTC, exclu de #91.","snapshot":{"id":"EVT-0289","packs":["COL-0065","COL-0070","COL-0082"],"title":"Alunissage d’Apollo 11","niveau":1,"topics":["Espace","Frontières et territoires","Géopolitique","Techniques et technologies"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":20,"start_year":1969,"date_status":"EXACT","description":"Le module lunaire d''Apollo se pose sur la Lune avec deux astronautes. Cet alunissage permet les premiers pas humains sur un autre astre et devient un symbole de la puissance scientifique américaine.","start_month":7,"playable_mode":"DAY","titre_question":"Alunissage d’Apollo 11"},"verified_sources":[{"url":"https://www.nasa.gov/mission/apollo-11/","evidence":"Alunissage du 20 juillet 1969, distinct du premier pas en UTC le 21 juillet.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0990","pack_id":"COL-0115","reason":"Objet majeur de culture numérique ; réutiliser la présentation, sans créer un lancement commercial homonyme.","snapshot":{"id":"EVT-0990","packs":["COL-0059","COL-0060","COL-0112"],"title":"Présentation du premier iPhone par Steve Jobs","niveau":1,"topics":["Économie","Techniques et technologies"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":9,"start_year":2007,"date_status":"EXACT","description":"Présentation du premier iPhone par Steve Jobs. Repère daté de 9 janvier 2007, lié à Économie et Techniques et technologies, avec un ancrage principal en Monde / global et États-Unis.","start_month":1,"playable_mode":"DAY","titre_question":null},"verified_sources":[{"url":"https://www.apple.com/ie/newsroom/2007/01/09Apple-Reinvents-the-Phone-with-iPhone/","evidence":"Annonce officielle du 9 janvier 2007, distincte de la commercialisation en juin.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0018","pack_id":"COL-0074","reason":"Déclaration fondatrice de la construction européenne actuellement absente de ce pack.","snapshot":{"id":"EVT-0018","packs":["COL-0061","COL-0082"],"title":"Déclaration Schuman","niveau":1,"topics":["Construction européenne","Décolonisation","Diplomatie","Géopolitique","Guerres et conflits","Organisations internationales"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":9,"start_year":1950,"date_status":"EXACT","description":"Robert Schuman propose de gérer ensemble le charbon et l''acier de plusieurs pays européens. Cette coopération doit rendre une nouvelle guerre plus difficile et préparer une Europe unie.","start_month":5,"playable_mode":"DAY","titre_question":null},"verified_sources":[{"url":"https://www.consilium.europa.eu/en/schuman-declaration/","evidence":"Déclaration du 9 mai 1950 confirmée par le Conseil.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0446","pack_id":"COL-0067","reason":"Prise de pouvoir de Bonaparte : entrée dans le Consulat.","snapshot":{"id":"EVT-0446","packs":["COL-0060","COL-0061","COL-0062","COL-0066","COL-0068","COL-0116"],"title":"Coup d’État du 18 Brumaire","niveau":1,"topics":["Diplomatie","Politique","Révolutions et insurrections"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":9,"start_year":1799,"date_status":"EXACT","description":"Coup d’État du 18 Brumaire — repère complémentaire du chapitre « Thème 1 — L’Europe face aux révolutions », daté 9 novembre 1799.","start_month":11,"playable_mode":"DAY","titre_question":"Coup d’État du 18 Brumaire"},"verified_sources":[{"url":"https://www.napoleon.org/histoire-des-2-empires/articles/autour-du-18-brumaire-contexte-et-deroulement-dun-coup-detat/","evidence":"Date retenue 18 brumaire/9 novembre ; coup d’État déroulé les 9 et 10. Réemploi du début canonique, sans correction silencieuse en plage.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0682","pack_id":"COL-0067","reason":"Proclamation de l’Empire, distincte du sacre déjà associé.","snapshot":{"id":"EVT-0682","packs":["COL-0059","COL-0060","COL-0061","COL-0062","COL-0081","COL-0116"],"title":"Proclamation de Napoléon Bonaparte comme empereur des Français","niveau":1,"topics":["Empires","Politique"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":18,"start_year":1804,"date_status":"EXACT","description":"Proclamation de Napoléon Bonaparte comme empereur des Français. Repère daté de 18 mai 1804, lié à Empires et Politique, avec un ancrage principal en Europe et France.","start_month":5,"playable_mode":"DAY","titre_question":null},"verified_sources":[{"url":"https://www.napoleon.org/histoire-des-2-empires/dossiers-thematiques/la-proclamation-de-lempire-18-mai-1804","evidence":"Sénatus-consulte du 18 mai 1804 ; ne pas confondre avec le sacre de décembre.","checked_on":"2026-10-16"}]},{"event_id":"EVT-0686","pack_id":"COL-0067","reason":"Début de l’invasion de la Russie : jalon majeur, sans dupliquer la campagne générale.","snapshot":{"id":"EVT-0686","packs":["COL-0060","COL-0062","COL-0069","COL-0081"],"title":"Début de l’invasion de la Russie par Napoléon","niveau":1,"topics":["Géopolitique","Guerres et conflits"],"end_day":null,"end_year":null,"playable":true,"end_month":null,"precision":"DAY","start_day":24,"start_year":1812,"date_status":"EXACT","description":"Début de l’invasion de la Russie par Napoléon. Repère daté de 24 juin 1812, lié à Géopolitique et Guerres et conflits, avec un ancrage principal en Europe et Russie / URSS.","start_month":6,"playable_mode":"DAY","titre_question":null},"verified_sources":[{"url":"https://www.napoleon.org/histoire-des-2-empires/chronologies/1812-la-campagne-de-russie-2-de-borodino-a-moscou","evidence":"Entrée en territoire russe le 24 juin 1812.","checked_on":"2026-10-16"}]}],"packs":[{"id":"COL-0067","slug":"epoque-napoleonienne","parent_id":null},{"id":"COL-0074","slug":"construction-europeenne","parent_id":null},{"id":"COL-0112","slug":"fun-grandes-premieres","parent_id":null},{"id":"COL-0115","slug":"fun-pop-culture","parent_id":null}]}'::jsonb;
  presents integer;
begin
  if exists(select 1 from histoire.migrations_appliquees where version='20261015222704') then return; end if;
  if not exists(select 1 from histoire.events) then
    raise notice 'A0 différé : importer le corpus local puis rejouer la migration';
    return;
  end if;
  if not exists(select 1 from histoire.migrations_appliquees where version='20261015201336') then
    raise exception 'A0 : administration #120 requise';
  end if;
  select count(*) into presents from jsonb_array_elements(manifeste->'associations') a
    join histoire.events e on e.id=a->>'event_id';
  if presents<>10 then raise exception 'A0 : corpus partiel (%/10) ; refaire audit et relecture',presents; end if;
  if exists(select 1 from jsonb_array_elements(manifeste->'packs') x
    left join histoire.packs p on p.id=x->>'id'
    where p.id is null or not p.active or p.slug is distinct from x->>'slug'
      or p.parent_id is distinct from x->>'parent_id') then
    raise exception 'A0 : pack cible absent ou modifié ; refaire audit et relecture';
  end if;
  -- Les modifications éditoriales antérieures ne sont jamais remplacées :
  -- une dérive depuis le dossier relu exige un nouvel audit avant insertion.
  if exists(select 1 from jsonb_array_elements(manifeste->'associations') x
    join histoire.events e on e.id=x->>'event_id'
    left join histoire.event_answers a on a.event_id=e.id
    where jsonb_build_object(
      'id',e.id,'title',e.title,'titre_question',e.titre_question,'niveau',e.niveau,
      'precision',e.precision,'playable',e.playable,'playable_mode',e.playable_mode,
      'date_status',e.date_status,'start_year',a.start_year,'start_month',a.start_month,'start_day',a.start_day,
      'end_year',a.end_year,'end_month',a.end_month,'end_day',a.end_day,'description',a.description)
      is distinct from ((x->'snapshot')-'packs'-'topics')) then
    raise exception 'A0 : événement, date ou correction modifié depuis le relevé ; refaire audit et relecture';
  end if;
  -- Ajouter à la suite sans déplacer les liens déjà ajoutés manuellement.
  with manquants as (
    select x->>'pack_id' pack_id,x->>'event_id' event_id,
      row_number() over(partition by x->>'pack_id' order by ordinalite) rang
    from jsonb_array_elements(manifeste->'associations') with ordinality a(x,ordinalite)
    where not exists(select 1 from histoire.pack_events pe where pe.pack_id=x->>'pack_id' and pe.event_id=x->>'event_id')
  )
  insert into histoire.pack_events(pack_id,event_id,position)
    select m.pack_id,m.event_id,((select coalesce(max(pe.position),0) from histoire.pack_events pe where pe.pack_id=m.pack_id)+m.rang)::integer
    from manquants m on conflict(pack_id,event_id) do nothing;
  -- Ce marqueur privé protège aussi les rattachements éditoriaux d'un import v18.
  -- Aucun faux auteur ni audit d'action administrateur n'est fabriqué.
  insert into histoire.admin_pack_additions(pack_id,event_id)
    select x->>'pack_id',x->>'event_id' from jsonb_array_elements(manifeste->'associations') x
    on conflict(pack_id,event_id) do nothing;
  -- Ne toucher ni pack_event_status, ni ses audits : un retrait reste retiré.
  insert into histoire.migrations_appliquees(version,nom)
    values('20261015222704','enrichissement_v12_a0');
end $a0$;$sql_a0$; end $test_a0$;
